var MULT = { requirements: 1, design: 5, coding: 10, testing: 20, production: 100 };
function cost(foundIn) {
  return Object.prototype.hasOwnProperty.call(MULT, foundIn) ? 0.5 * MULT[foundIn] : null;
}
function totalCost(defects) {
  return Object.keys(defects).reduce(function (s, p) { var c = cost(p); return c === null ? s : s + c * defects[p]; }, 0);
}
// Later: 4 × 10 + 2 × 50 = 140 h. With the review: 2 h + 6 × 0.5 h = 5 h. Saved: 135 h.
const SAVED_BY_REVIEW = totalCost({ testing: 4, production: 2 }) - (2 + totalCost({ requirements: 6 }));
